(6856837, 1031876, 144365, '<td valign="top">#2<br/>In most of the entries I was looking for something that didn''t belong. Unfortunately for this chap, that''s everywhere. The mustache takes it over the edge, and enough to get my sole second highest vote.</td>', '#2In most of the entries I was looking for something that didn''t belong. Unfortunately for this chap, that''s everywhere. The mustache takes it over the edge, and enough to get my sole second highest vote.', '2012-09-05 11:59:20.000000', NULL, 1),
(6856840, 1031759, 144365, '<td valign="top">#3<br/>Like the playful idea. The composition of the car was well placed and warranted a chuckle. In return I gave it my sole third highest vote.</td>', '#3Like the playful idea. The composition of the car was well placed and warranted a chuckle. In return I gave it my sole third highest vote.', '2012-09-05 12:00:29.000000', NULL, 1),
